-- aria:dispatch-vehicle-details was missing 4 fields the M10.ReturnStockIn
-- flow needs: invoice/stock-return count, box weight, oil type (dispatch_vehicle_detail
-- already has these columns via V47 projection -- the page just never exposed them),
-- plus a read-only display of which supervisor QC allocated for unloading
-- (qc_unloading_approval.unloading_supervisor_id, resolved to a name via a join).
--
-- QcUnloadingApproval is registered here purely so the generic datasource-join
-- engine (DataSourceQueryService) can resolve it by name in joins[] -- read-only
-- lookup use, no write path needed, matching GatePass's read_role='*' convention.

INSERT INTO entity_registry (tenant_id, code, display_name, table_name, description, category, read_role, write_role)
SELECT -1, 'QcUnloadingApproval', 'QC Unloading Approval', 'qc_unloading_approval',
  'QC Approval page capture (oil/packing/FG params, decision, unloading assignment). Read-only join target.',
  'M10', '*', 'TenantAdmin'
WHERE NOT EXISTS (SELECT 1 FROM entity_registry WHERE tenant_id = -1 AND code = 'QcUnloadingApproval');

UPDATE page_version pv JOIN page_definition pd ON pd.id = pv.page_id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":["vehicleNo","gpNumber","flowVariant","currentState"]}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","required":true,"placeholder":"Select vehicle awaiting dispatch entry","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"},{"entity":"QcUnloadingApproval","as":"qua","on":"gate_pass.workflow_instance_id = qua.workflow_instance_id"},{"entity":"Employee","as":"uemp","on":"qua.unloading_supervisor_id = uemp.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"Dispatch"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","vehicle_no","uemp.employeename as unloadingSupervisorName"],"sort":[{"field":"vehicle_no","dir":"asc"}]},"valueField":"vehicle_no","labelField":"vehicle_no"},"onChangeFill":{"flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id","unloadingSupervisorName":"unloadingSupervisorName"}},{"kind":"FormField","type":"text","name":"flowVariantCode","label":"Flow Variant","disabled":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Loading Type","disabled":true},{"kind":"FormField","type":"text","name":"instanceId","label":"Workflow Instance","disabled":true},{"kind":"FormField","type":"select","name":"ownershipType","label":"Ownership","options":["OWN VEHICLE","HIRED VEHICLE"]},{"kind":"FormField","type":"text","name":"driverName","label":"Driver Name"},{"kind":"FormField","type":"text","name":"driverPhone","label":"Driver Contact"},{"kind":"FormField","type":"text","name":"brokerName","label":"Broker Details","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"text","name":"invoiceNo","label":"Invoice No","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"number","name":"invoiceQty","label":"Invoice Qty","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"text","name":"vendorName","label":"Vendor Details","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"text","name":"oilRmItem","label":"Oil RM Details","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound''"},{"kind":"FormField","type":"text","name":"tankerNo","label":"Tanker Number","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound''"},{"kind":"FormField","type":"select","name":"poVerified","label":"PO Verified","options":["YES","NO - MANAGER APPROVAL"],"visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"text","name":"poOverrideReason","label":"Reason (if PO not verified)","visibleWhen":"(#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES''","requiredWhen":"(#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES''"},{"kind":"FormField","type":"text","name":"dispatchOfficerName","label":"Dispatch Front Officer Name","visibleWhen":"#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"text","name":"transportName","label":"Transport Name","visibleWhen":"#form.flowVariantCode == ''M10.PackLoading'' || #form.flowVariantCode == ''M10.FGLoading'' || #form.flowVariantCode == ''M10.TankerOutbound''"},{"kind":"FormField","type":"textarea","name":"packingFgStockDetails","label":"Packing / FG Stock Details","visibleWhen":"#form.flowVariantCode == ''M10.PackLoading'' || #form.flowVariantCode == ''M10.FGLoading'' || #form.flowVariantCode == ''M10.PackUnload''"},{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"No. of Invoice / Stock Return Count","visibleWhen":"#form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)","visibleWhen":"#form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type","visibleWhen":"#form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"FormField","type":"text","name":"unloadingSupervisorName","label":"Unloading Supervisor Allocated","disabled":true,"visibleWhen":"#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","variant":"primary"}]}],"entity":"DispatchVehicleDetail"}'
WHERE pd.code = 'aria:dispatch-vehicle-details' AND pv.id = pd.current_version_id
  AND JSON_SEARCH(pv.body_json, 'one', 'invoiceReturnCount', NULL, '$.layout[*].fields[*].name') IS NULL;
